WFJ.Data.add("book", {
  ["48329bb2d723ab11"] = { "あの夜なぜ私が生き延びたのか、推し量ることしかできない。私はいつも用心深く、突きをすばやくかわし、落とし穴を跳び越えてきた。私のあだ名もこの性分から来ている。だから、命を救ったのはただその用心深さの才だったのかもしれない……\n\nあるいは、瓦礫から引き抜いたScytheのおかげかもしれない。Scytheそのものではありえない。必死に逃げる途中でなくしてしまったのだから。だが、WorgenをDuskwoodに呼び寄せたのが私だとすれば、Worgenは私にまれな礼儀を示したのかもしれない。呪われるがいい。", "." },
  ["4858f66707a9f824"] = { "幸運を祈る。そして、Urokの手下との試練に役立つかもしれぬ手がかりを授けよう。\n\nOmokkがogreに対して使う呪文、奴らを打ち殺すあの呪文は、Omokkを殺した後もなお力を持っているかもしれぬ。Urokの手下との戦いの最中に、Omokkの首に宿る力を呼び起こせ――運が良ければ、OmokkがUrokの手下どもを打ち倒すであろう！\n\nなんともふさわしい皮肉よ。", "." },
  ["4859f6f4a4857033"] = { "Kel'ThuzadがLordaeronで成功を収めると、Lich Kingは人間の文明への攻撃に向けて最後の準備を整えた。Ner'zhulは疫病のエネルギーを、疫病の大釜と呼ばれるいくつもの持ち運べる遺物に込め、Kel'Thuzadにそれらの大釜をLordaeronへ運ばせ、カルトが支配する様々な村に隠すよう命じた。", "." },
  ["489579a033cd7a8c"] = { "dreadlordsの絶え間ない監視のもとでLich Kingが増大する力を使いこなしていくうちに、彼は広大なDragonblightの外れにある人里離れた人間の集落を見つけた。気まぐれに、Ner'zhulは何も知らない人間たちで自らの力を試してみることにした。", "." },
  ["48962658def204fd"] = { "原初の世界Azerothを見つけ、Well of Eternityの無限のエネルギーを感じ取ったSargerasは、飽くことのない渇望に呑み込まれた。Nameless Voidの偉大なる闇の神は、この若い世界を滅ぼし、そのエネルギーを我がものにしようと決意した。", "." },
  ["4896980d431ed8db"] = { "Lord Stoutmantle——\n\nTownship of Lakeshireは、謹んで貴殿の民兵団の援助をお願い申し上げます。この手紙を書いている今も、我々はBlackrock OrcsとMorganthのShadowhide Gnollsの双方に包囲されております。事態が深刻でなければ、このような要請はいたしません。Stormwindからの援助を待っておりますが、その助けが届くまで、どうかお力をお貸しください。王国が破られれば、人間すべてが危機に陥るのです。\n\nMagistrate Solomon", "." },
  ["48b3402fdf347d79"] = { "大内戦によって土地が廃墟と化した後、残りのGurubashiの部族はそれぞれの道を歩んだ。Skullsplitter、Bloodscalp、Darkspearの各部族は、Stranglethornの広大なジャングルの中に自らの土地を求めて旅立った。砕けた帝国にはもろい平和が訪れたが、Hakkarがいつの日か世界に再び生まれ変わり――その日――世界を丸ごと呑み込むという予言を口にする者もいた。", "." },
  ["48c04b38cdd29d65"] = { "第4章 - Dun Baldar Bunkers\n\nすでにお気づきのとおり、Stormpikeの防御層は、一度の強力な攻勢で全軍が崩されることのないように配置されている。聞かれる前に言っておくが、そうだ、我が軍もまさにこの配置であり、いや、我らの防御構造を変えるつもりはない。真似をしたのは向こうだ、なぜこちらが変えねばならん？", "." },
})
